INSERT INTO tasks (id, slug, name, outcome, guidance, sort_order, is_published, published_at, created_at, updated_at) VALUES ('task_create_a_short_product_video', 'create-a-short-product-video', 'Create a short product video', 'Produce a short video that explains or promotes a product.', 'Choose the production method before the tool: use generated actors for repeatable ad variants, record the real product when trust depends on its interface, or begin with a brand system when consistency across channels matters most.', 1, 1, unixepoch(), unixepoch(), unixepoch()) ON CONFLICT(slug) DO UPDATE SET name = excluded.name, outcome = excluded.outcome, guidance = excluded.guidance, sort_order = excluded.sort_order, is_published = 1, updated_at = unixepoch();
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_create_a_short_product_video', 'tool_adant', 1, 'you need AI-generated actors and many vertical ad variants quickly', 'Starts from a product link, brief, or reference and combines format research with batch generation for social ads.', 'Generation is credit-based; paid Pro and Max allowances determine the volume available after the free sign-up credits.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_create_a_short_product_video', 'tool_capptivo', 2, 'you need to record the real software interface and turn it into a polished demo', 'Records genuine screen flows, then adds cursor zoom, captions, annotations, backgrounds, and multiple export formats.', 'It records and polishes an existing product experience rather than generating actors, scenes, or product footage.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_create_a_short_product_video', 'tool_zawa', 3, 'you need product video assets that stay consistent with a wider brand system', 'Carries a generated identity system into product, UGC-style, and social assets alongside the wider campaign kit.', 'It is a broad creative suite, and its exact free and paid usage limits are not currently public.');
INSERT INTO tasks (id, slug, name, outcome, guidance, sort_order, is_published, published_at, created_at, updated_at) VALUES ('task_create_on_brand_campaign_visuals', 'create-on-brand-campaign-visuals', 'Create on-brand campaign visuals', 'Produce a consistent set of campaign images and visual assets.', 'Choose by where consistency should come from: detailed canvas control, a reusable identity system, or an agent that remembers the brand while working across several creative formats.', 2, 1, unixepoch(), unixepoch(), unixepoch()) ON CONFLICT(slug) DO UPDATE SET name = excluded.name, outcome = excluded.outcome, guidance = excluded.guidance, sort_order = excluded.sort_order, is_published = 1, updated_at = unixepoch();
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_create_on_brand_campaign_visuals', 'tool_playyy', 1, 'you want hands-on control over the layers and details of each campaign image', 'Keeps generated elements editable on a layer-aware canvas so a team can refine and resize the visual direction itself.', 'Its current public workflow is image-focused; the official page still lists image-to-video as coming soon.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_create_on_brand_campaign_visuals', 'tool_zawa', 2, 'you need to create the brand identity before producing the campaign assets', 'Generates the logo, palette, type direction, and guidelines that later assets can reuse across channels.', 'The suite covers many creative jobs, but exact current free and paid usage limits remain unverified.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_create_on_brand_campaign_visuals', 'tool_miora', 3, 'you need one remembered brand direction across image, video, UI, and 3D work', 'Combines memory, reusable skills, and an editable canvas for image, video, UI, and 3D campaign work.', 'The workflow is credit-based; the free 1,000 sign-up credits expire after 90 days and advanced models are limited.');
INSERT INTO tasks (id, slug, name, outcome, guidance, sort_order, is_published, published_at, created_at, updated_at) VALUES ('task_test_a_web_app_before_release', 'test-a-web-app-before-release', 'Test a web app before release', 'Find release-blocking web issues and keep evidence close to the fix.', 'Choose the testing boundary first: an agent-led development loop, broad browser and real-device execution, or a focused checklist review of the pages a client or customer will see.', 3, 1, unixepoch(), unixepoch(), unixepoch()) ON CONFLICT(slug) DO UPDATE SET name = excluded.name, outcome = excluded.outcome, guidance = excluded.guidance, sort_order = excluded.sort_order, is_published = 1, updated_at = unixepoch();
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_test_a_web_app_before_release', 'tool_coldtea', 1, 'you want QA to stay inside the same agent-led development loop as the code', 'Keeps coding-agent context, plain-language regression tests, review, and production monitoring in one macOS environment.', 'It is macOS-focused and expects an existing development project plus external coding-agent tooling.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_test_a_web_app_before_release', 'tool_testmu_ai', 2, 'you need broad browser, framework, CI, and real-device test coverage', 'Provides cloud infrastructure for authoring, executing, analyzing, and healing tests across a large testing matrix.', 'It is a full cloud quality-engineering platform, so setup and operational scope are heavier than a focused site review.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_test_a_web_app_before_release', 'tool_superflow_ai', 3, 'you need a focused final check of live or staging pages before sign-off', 'Turns a reusable review checklist into agents that pin screenshot-backed accessibility, copy, link, and metadata findings to the page.', 'It is a review-and-evidence workflow, not a real-device matrix or a code-level automated test runner.');
INSERT INTO tasks (id, slug, name, outcome, guidance, sort_order, is_published, published_at, created_at, updated_at) VALUES ('task_work_with_spoken_content_across_languages', 'work-with-spoken-content-across-languages', 'Work with spoken content across languages', 'Dictate, transcribe, translate, or understand spoken material across languages.', 'Choose by where the audio begins and where the result must go: private speech on a Mac, translated YouTube playback, or voice that should become text inside any desktop app.', 4, 1, unixepoch(), unixepoch(), unixepoch()) ON CONFLICT(slug) DO UPDATE SET name = excluded.name, outcome = excluded.outcome, guidance = excluded.guidance, sort_order = excluded.sort_order, is_published = 1, updated_at = unixepoch();
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_work_with_spoken_content_across_languages', 'tool_zen_whisper', 1, 'you want dictation and media transcription to stay primarily on your Mac', 'Runs core recognition on Apple Silicon and can type at the active cursor or transcribe uploaded media without making cloud processing the default.', 'It is Mac-focused, and optional network-backed features have different privacy boundaries from core local recognition.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_work_with_spoken_content_across_languages', 'tool_hearsub', 2, 'you are watching YouTube in another language and need subtitles or dubbing now', 'Works inside the viewing session, showing bilingual subtitles and synchronized dubbing without a separate full-video upload workflow.', 'It is a browser-extension workflow for supported YouTube videos, not a general transcription or media-editing application.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_work_with_spoken_content_across_languages', 'tool_lispr', 3, 'you want to speak in one language and write translated text into any desktop app', 'Uses push-to-talk input at the active cursor and can translate spoken input before inserting text into the current application.', 'Transcription requires its cloud service; audio is encrypted and discarded by default but the workflow is not local-first.');
INSERT INTO tasks (id, slug, name, outcome, guidance, sort_order, is_published, published_at, created_at, updated_at) VALUES ('task_turn_documents_into_source_backed_analysis', 'turn-documents-into-source-backed-analysis', 'Turn documents into source-backed analysis', 'Analyse documents while keeping important claims traceable to source material.', 'Choose by the deliverable and confidentiality boundary: an enterprise strategy output, private retrieval on a local Windows machine, or specialist legal analysis tied to authority and source passages.', 5, 1, unixepoch(), unixepoch(), unixepoch()) ON CONFLICT(slug) DO UPDATE SET name = excluded.name, outcome = excluded.outcome, guidance = excluded.guidance, sort_order = excluded.sort_order, is_published = 1, updated_at = unixepoch();
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_turn_documents_into_source_backed_analysis', 'tool_decisity', 1, 'you need source-traceable strategy analysis and a board-ready deliverable', 'Structures a brief and uploaded sources through specialist analysis and review, then keeps claims linked to documents or public URLs.', 'It is a contact-sales enterprise workflow rather than a lightweight self-serve document chat.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_turn_documents_into_source_backed_analysis', 'tool_lumichats_offline', 2, 'your documents must remain on a Windows computer while you question them', 'Runs GGUF models and document embeddings on the device without requiring a GPU or a cloud connection.', 'It requires Windows 10 or 11 and at least 8 GB RAM; answer quality depends on the local model selected.');
INSERT INTO task_items (task_id, tool_id, sort_order, best_for, key_difference, limitation) VALUES ('task_turn_documents_into_source_backed_analysis', 'tool_vaquill_ai', 3, 'you are researching law, reviewing contracts, or checking compliance requirements', 'Returns verified citations and source passages from documents, case law, and other legal authority for specialist review.', 'The workflow is legal-specific and moves to paid plans after its seven-day trial.');
