INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_zen_whisper', 'Zen Whisper', 'Local-first Mac dictation and transcription that types into your existing apps.', 'Zen Whisper runs core speech recognition on Apple Silicon Macs, supports dictation at the active cursor, and can transcribe uploaded media. Its official documentation distinguishes on-device recognition from optional network-backed features.', 'Writing & Language Voice & Speech Productivity', 'Dictation Transcription Desktop app Local first Multilingual Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_lispr', 'Lispr', 'Push-to-talk dictation and translation that writes into your current desktop app.', 'Lispr provides cursor-level voice dictation on macOS and Windows, with speech input across nearly 100 languages and optional translation into 32 output languages. Its cloud transcription service encrypts audio in transit and discards it after transcription by default.', 'Writing & Language Voice & Speech Productivity', 'Dictation Transcription Translation Desktop app Multilingual Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_playyy', 'Playyy', 'Generate and edit campaign visuals on a layer-aware AI canvas.', 'Playyy combines text-to-image generation with an editable canvas for refining elements, removing backgrounds, expanding images, and adapting visual assets to different formats.', 'Image & Design Marketing & Sales', 'Image generation Image editing Web app Free plan No-code');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_miora', 'Miora', 'Build brand-consistent campaign assets with a creative agent, editable canvas, and memory.', 'Miora combines a free-form canvas, a creative agent, reusable skills, and memory for producing brand visual systems and campaign assets across image, video, UI, and 3D workflows.', 'Image & Design Video & Animation Marketing & Sales', 'Image generation Brand design Video generation Web app Free plan No-code');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_capptivo', 'Capptivo', 'Open-source screen recording and editing for polished product demos.', 'Capptivo records screens on macOS, Windows, and Linux, then adds cursor-following zoom, annotations, captions, background styling, and multi-format exports in a local desktop editor.', 'Video & Animation Productivity', 'Screen recording Video editing Desktop app Open source Local first Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_hearsub', 'HearSub', 'Real-time YouTube subtitle translation with synchronized AI dubbing.', 'HearSub is a browser extension that translates supported YouTube videos during playback, showing bilingual subtitles and generating synchronized dubbing without requiring a full video upload.', 'Voice & Speech Video & Animation Research & Data', 'Translation Dubbing Transcription Browser extension Multilingual Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_coldtea', 'Coldtea', 'An agentic development environment spanning code, release testing, and monitoring.', 'Coldtea brings coding-agent sessions, task context, plain-language regression tests, and production monitoring into one macOS development environment. Cloud execution is optional and its terminal is available without a paid plan.', 'Coding & Development Automation & Agents', 'Coding assistant Software testing DevOps and monitoring Desktop app Local first Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_hey_noah', 'Hey Noah', 'An AI executive assistant for scheduling, follow-ups, and meeting logistics.', 'Hey Noah coordinates meetings by email or text, checks calendars, handles scheduling back-and-forth, prepares meeting context, and follows through on notes and action items.', 'Productivity Automation & Agents', 'Meeting assistant Scheduling Workflow automation Web app');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_adant', 'AdAnt', 'Research winning formats and generate batches of short-form social ads with a creative agent.', 'AdAnt is an agentic video studio for researching social-ad formats, turning a product link, brief, or reference video into creative directions, and generating batches of short-form variants for TikTok, Instagram Reels, and YouTube Shorts.', 'Marketing & Sales Video & Animation', 'Ad creative Social media Video generation Web app API Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_decisity', 'Decisity', 'Source-traceable strategy analysis and board-ready deliverables.', 'Decisity structures strategy work from a brief and uploaded documents through specialist analysis, review, and export. Its official product pages state that claims link back to source documents or public URLs.', 'Research & Data Productivity', 'Business research Document analysis Web app');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_vaquill_ai', 'Vaquill AI', 'Research and review legal documents with citations linked to the underlying authority.', 'Vaquill AI supports legal research, contract review, compliance checks, and document chat for legal and corporate teams. Its research workflow returns verified citations and source passages from documents and case law.', 'Research & Data Productivity', 'Legal research Document analysis Web app API');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_soloop', 'Soloop', 'An approval-first agent workspace for solo founders building demand.', 'Soloop proposes one next move, waits for founder approval, and delegates research, social, or coding work to named agents while returning results to a shared workspace.', 'Automation & Agents Productivity Marketing & Sales Coding & Development', 'Workflow automation Business research Coding assistant Web app');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_lumichats_offline', 'LumiChats Offline', 'Run and chat with local language models on Windows without a GPU.', 'LumiChats Offline is a free Windows application for running GGUF language models locally, including private document chat with on-device embeddings and no required cloud connection.', 'Coding & Development Research & Data Productivity', 'Local models Knowledge management Desktop app Open source Local AI Local first Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_testmu_ai', 'TestMu AI', 'AI-assisted quality engineering across browsers, devices, and test frameworks.', 'TestMu AI provides a cloud for authoring, executing, analyzing, and healing software tests across browser automation frameworks and real devices, with natural-language agent tooling available for selected workflows.', 'Coding & Development Automation & Agents', 'Software testing Web app API Free plan');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_superflow_ai', 'Superflow AI', 'Run reusable QA checklists against live or staging websites and pin findings to the page.', 'Superflow AI turns a review checklist into QA agents that inspect websites for issues such as accessibility, broken links, spelling, and social metadata, then return screenshot-backed findings for human sign-off.', 'Coding & Development Productivity Automation & Agents', 'Software testing Web app Free plan No-code');
INSERT INTO tools_fts (tool_id, name, tagline, description, category_names, tag_names) VALUES ('tool_zawa', 'Zawa', 'Generate editable brand kits and visual marketing assets from a brief.', 'Zawa creates brand identity directions, logos, palettes, typography, mockups, posters, and social assets from a business description, with reusable brand guidelines for later designs.', 'Image & Design Marketing & Sales', 'Brand design Image generation Web app Free plan No-code');
